-- Application bindings
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.bind("SUPER + ALT + RETURN", hl.dsp.exec_cmd("uwsm-app -- xdg-terminal-exec --dir=\"$(solace-cmd-terminal-cwd)\" tmux new"), { description = "Tmux" })
hl.bind("SUPER + RETURN", hl.dsp.exec_cmd("uwsm-app -- xdg-terminal-exec --dir=\"$(solace-cmd-terminal-cwd)\""), { description = "Terminal" })
hl.bind("SUPER + SHIFT + RETURN", hl.dsp.exec_cmd("solace-launch-browser"), { description = "Browser" })
hl.bind("SUPER + SHIFT + F", hl.dsp.exec_cmd("uwsm-app -- nautilus --new-window"), { description = "File manager" })
hl.bind("SUPER + ALT + SHIFT + F", hl.dsp.exec_cmd("uwsm-app -- nautilus --new-window \"$(solace-cmd-terminal-cwd)\""), { description = "File manager (cwd)" })
hl.bind("SUPER + SHIFT + B", hl.dsp.exec_cmd("solace-launch-browser"), { description = "Browser" })
hl.bind("SUPER + SHIFT + ALT + B", hl.dsp.exec_cmd("solace-launch-browser --private"), { description = "Browser (private)" })
hl.bind("SUPER + SHIFT + M", hl.dsp.exec_cmd("solace-launch-or-focus spotify"), { description = "Music" })
hl.bind("SUPER + SHIFT + ALT + M", hl.dsp.exec_cmd("solace-launch-or-focus-tui cliamp"), { description = "Music TUI" })
hl.bind("SUPER + SHIFT + N", hl.dsp.exec_cmd("solace-launch-editor"), { description = "Editor" })
hl.bind("SUPER + SHIFT + D", hl.dsp.exec_cmd("solace-launch-tui lazydocker"), { description = "Docker" })
hl.bind("SUPER + SHIFT + G", hl.dsp.exec_cmd("solace-launch-or-focus ^signal$ \"uwsm-app -- signal-desktop\""), { description = "Signal" })
hl.bind("SUPER + SHIFT + O", hl.dsp.exec_cmd("solace-launch-or-focus ^obsidian$ \"uwsm-app -- obsidian\""), { description = "Obsidian" })

-- If your web app url contains #, type it as ## to prevent hyprland treating it as a comment
hl.bind("SUPER + SHIFT + A", hl.dsp.exec_cmd("solace-launch-webapp \"https://chatgpt.com\""), { description = "ChatGPT" })
hl.bind("SUPER + SHIFT + X", hl.dsp.exec_cmd("solace-launch-webapp \"https://aur.archlinux.org/\""), { description = "AUR" })
hl.bind("SUPER + SHIFT + Z", hl.dsp.exec_cmd("solace-launch-webapp \"https://archlinux.org/packages/\""), { description = "Arch Packages" })

